package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF4J;
import org.eclipse.rdf4j.model.vocabulary.SESAME;
import org.junit.jupiter.api.Test;

/** Future source-level controls; apply with the helper, never as the pre-source baseline patch. */
class LmdbContextRequestsTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void emptyAndSingletonRequestsReturnTheSameArray() {
		for (Resource[] request : new Resource[][] { {}, { null }, { RDF4J.NIL }, { SESAME.NIL },
				{ VF.createIRI("urn:context-request:unknown") } }) {
			assertSame(request, LmdbContextRequests.distinct(request));
		}
	}

	@Test
	void rdfEqualityRetainsFirstRepresentativeAndOrderWithoutMutatingCaller() {
		Resource first = VF.createIRI("urn:context-request:first");
		Resource equal = VF.createIRI(first.stringValue());
		assertNotSame(first, equal);
		assertEquals(first, equal);
		Resource[] request = { first, null, RDF4J.NIL, equal, SESAME.NIL, null, RDF4J.NIL };
		Resource[] original = request.clone();
		Resource[] distinct = LmdbContextRequests.distinct(request);
		assertArrayEquals(new Resource[] { first, null, RDF4J.NIL, SESAME.NIL }, distinct);
		assertSame(first, distinct[0]);
		assertArrayEquals(original, request);
	}

	@Test
	void distinctRawNilGraphsAndPhysicalDefaultRemainDistinct() {
		Resource[] request = { null, RDF4J.NIL, SESAME.NIL };
		assertSame(request, LmdbContextRequests.distinct(request));
	}
}
